const PAYLOAD = [{"id":"pnj-aseryns-terres-temples-heither-scorn-33","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Heither Scorn","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Heither Scorn","real_name_source":"Heither Scorn","nom_verite":"Heith Skoptidottir","nom_verite_source":"Heith Skoptidottir","race":"Aseryne (Hyperboréenne)","age":"24 ans","origine":"Islandaise","statut":"reine","affiliations":"crawlers : hookers","source_group":"Hyperborée","source_order":33,"source_page":34,"identity_keys":["Heith Skoptidottir","Heither Scorn"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Reine : Heith Skoptidottir Nom de la Réalité : Heither Scorn Nom de la Vérité : Heith Skoptidottir Age : «24 ans » - ??? Affiliations : crawlers : hookers Nationalité d’origine : Islandaise Ethnie réelle : Aseryne (Hyperboréenne) Statut : reine Heither est une beauté rousse qui, forcément, par sa plastique évoque de loin Siobhain. Avec le succès de la glorieuse actrice, elle obtint aisément des rôles, les rousses étant très appréciée même encore en 2035, mais son caractère de diva impétueuse la mena à cesser sa carrière d’actrice pour se concentrer sur le métier d’hôtesse et de barmaid, détenant un bar minuscule nommé le « Frozen Juice ». Bien que fou d’Aslaug, Siegorn dégoutait physiquement sa première épouse, alors, malgré une affection réelle qu’elle avait pour lui, il se maria à une seconde femme, Heith de la maison des Skadd qui règnent sur le duché d’ydalira. Insensible et dégoutée d’être elle aussi privée de ses droits d’héritage par ce mariage forcé, elle donna un enfant à Siegorn malgré tout, Hildegorn. Méprisante et intransigeante, Heith est une femme emplie de haine et de colère, servir d’utérus pour un gamin corrompu n’est pas un plan d’avenir qui lui convient et maintenant qu’elle a rempli son rôle, elle a obtenu le droit de résider en Californie. Hélas, rien ne lui convient à Los Angeles, rien ne comble le vide immense qu’elle ressent, rien ne l’excite ou ne l’intéresse. Elle a un léger intérêt pour la légende de Rylias, sur Mû, cherchant à se rapprocher des Mûliens pour visiter leur continent.","source_pages":[34,34],"source_designation":"Reine : Heith Skoptidottir"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Heither Scorn"],["Âge apparent","24 ans"],["Nationalité déclarée","Islandaise"]]},{"type":"p","text":"Heither est une beauté rousse qui, forcément, par sa plastique évoque de loin Siobhain. Avec le succès de la glorieuse actrice, elle obtint aisément des rôles, les rousses étant très appréciées même encore en 2035, mais son caractère de diva impétueuse la mena à cesser sa carrière d’actrice pour se concentrer sur le métier d’hôtesse et de barmaid, détenant un bar minuscule nommé le « Frozen Juice »."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Reine : Heith Skoptidottir"],["Nom de la Réalité","Heither Scorn"],["Nom de la Vérité","Heith Skoptidottir"],["Âge complet","24 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers : hookers"],["Nationalité d’origine","Islandaise"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","reine"]]},{"type":"p","style":"lore","text":"Bien que fou d’Aslaug, Siegorn dégoutait physiquement sa première épouse, alors, malgré une affection réelle qu’elle avait pour lui, il se maria à une seconde femme, Heith de la maison des Skadd qui règnent sur le duché d’ydalira. Insensible et dégoutée d’être elle aussi privée de ses droits d’héritage par ce mariage forcé, elle donna un enfant à Siegorn malgré tout, Hildegorn. Méprisante et intransigeante, Heith est une femme emplie de haine et de colère, servir d’utérus pour un gamin corrompu n’est pas un plan d’avenir qui lui convient et maintenant qu’elle a rempli son rôle, elle a obtenu le droit de résider en Californie. Hélas, rien ne lui convient à Los Angeles, rien ne comble le vide immense qu’elle ressent, rien ne l’excite ou ne l’intéresse. Elle a un léger intérêt pour la légende de Rylias, sur Mû, cherchant à se rapprocher des Mûliens pour visiter leur continent."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-bob-jotson-34","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Bob Jotson","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Bob Jotson","real_name_source":"Bob Jotson","nom_verite":"Borgar Ulfljotsson","nom_verite_source":"Borgar Ulfljotsson","race":"Aseryne (Hyperboréenne)","age":"46 ans","origine":"Américaine","statut":"Duc","affiliations":"Crawlers :fixers","source_group":"Hyperborée","source_order":34,"source_page":35,"identity_keys":["Borgar Ulfljotsson (Njormis)","Njormis","Bob Jotson","Borgar Ulfljotsson"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Glitniris : Borgar Ulfljotsson (Njormis) Nom de la Réalité : Bob Jotson Nom de la Vérité : Borgar Ulfljotsson Age : « 46 ans » - ??? Affiliations : Crawlers :fixers Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Hyperboréenne) Statut : Duc Bob Jotson est un fixer itinérant, on le croise un peu partout. C’est un grand amateur de cuisine qui ne se croise que dans des restaurants de tout niveau, du dinner bas de gamme des quartiers abandonnés aux plus grands restaurants. Il a toujours des missions très rentables pour les crawlers qui traitent avec lui, on le surnomme « le gourmet » dans le milieu car ses missions sont assez difficiles vu comme elles payent bien. Duc Hyperboréen, il est à la tête de la famille Njormis, même si on le penserait roturier il n’en est rien, c’est un très haut noble aseryn avec une éducation exemplaire. Il est réputé pour son sens de la justice et ce n’est pas pour rien puisque le palais ducal de Glitnir est à l’honneur de Forseti, le dieu nordique de la Justice qui n’est autre que Satan dans la Vérité. C’est donc autant la demeure du duc que le temple de la justice et, de fait, le haut tribunal d’Hyperborée. Si Borgar s’aventure en Californie c’est parce qu’en tant que gardien de la Justice dans le royaume, il lui incombe de faire appliquer ses jugements. Or, la renégate, Neera Athren a été reconnue coupable d’avoir tué son seigneur avant de fonder le Xenoshield, ce seigneur n’ayant pas reconnu l’attaque rocréenne sur ses terres qu’il ‘n’endigua pas.","source_pages":[35,35],"source_designation":"Duché de Glitniris : Borgar Ulfljotsson"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Bob Jotson"],["Âge apparent","46 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Bob Jotson est un fixer itinérant, on le croise un peu partout. C’est un grand amateur de cuisine qui ne se croise que dans des restaurants de tout niveau, du dinner bas de gamme des quartiers abandonnés aux plus grands restaurants. Il a toujours des missions très rentables pour les crawlers qui traitent avec lui, on le surnomme « le gourmet » dans le milieu car ses missions sont assez difficiles au regard de leur rémunération."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Glitniris : Borgar Ulfljotsson (Njormis)"],["Nom de la Réalité","Bob Jotson"],["Nom de la Vérité","Borgar Ulfljotsson"],["Âge complet","46 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers :fixers"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","Duc"]]},{"type":"p","style":"lore","text":"Duc Hyperboréen, il est à la tête de la famille Njormis, même si on le penserait roturier il n’en est rien, c’est un très haut noble aseryn avec une éducation exemplaire. Il est réputé pour son sens de la justice et ce n’est pas pour rien puisque le palais ducal de Glitnir est à l’honneur de Forseti, le dieu nordique de la Justice qui n’est autre que Satan dans la Vérité. C’est donc autant la demeure du duc que le temple de la justice et, de fait, le haut tribunal d’Hyperborée. Si Borgar s’aventure en Californie c’est parce qu’en tant que gardien de la Justice dans le royaume, il lui incombe de faire appliquer ses jugements. Or, la renégate, Neera Athren a été reconnue coupable d’avoir tué son seigneur avant de fonder le Xenoshield, ce seigneur n’ayant pas reconnu l’attaque rocréenne sur ses terres qu’il ‘n’endigua pas."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-ashilirei-saebbidottir-35","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Ashilirei Sæbbidottir","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Ashilirei Sæbbidottir","nom_verite_source":"Ashilirei Saebbidottir","race":"Aseryne (hyperboréenne)","age":"54 ans en apparence ; âge réel inconnu","origine":"Hyperboréenne","statut":"Duchesse de Volkvangra","affiliations":"_","source_group":"Hyperborée","source_order":35,"source_page":35,"identity_keys":["Ashilirei Sæbbidottir (Valgardis)","Valgardis","Ashilirei Saebbidottir","Ashilirei Sæbbidottir"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Volkvangra : Ashilirei Sæbbidottir (Valgardis) Nom de la Réalité : _ Nom de la Vérité : Ashilirei Saebbidottir Age : «54 ans » - ??? Affiliations : _ Nationalité d’origine : Hyperboréenne Ethnie réelle : Aseryne (hyperboréenne) Statut : Duchesse de Volkvangra Ashilirei était régulièrement considérée comme la plus belle femme de tout Hyperborée. L’âge et l’embonpoint lui ont fait perdre ce statut cependant, son influence et sa notoriété sont les plus grandes du continent. La reine-mère et le roi ont cruellement besoin du soutien de la maison Valgardis pour éviter que le conseil des magiciens ne renverse la couronne comme ils le projettent depuis longtemps. Elle a marié sa fille ainée, Aslaug alors qu’elle la désirait voir lui succéder, un sacrifice qui lui a assuré une place de conseillère dans le cercle de la reine-mère. Pourtant, Ashilirei et Hildeveig ne s’aiment pas du tout, et pour cause, la maison Valgardis est issue des immigrés atlantes alors qu’Hildeveig est issue des premiers colons, elles se méprisent réciproquement tout en s’utilisant. Elle vénère Lilith, « Freyja » dans la mythologie nordique, et son palais ducal est aussi un temple de la déesse, Ashilirei essaie d’ailleurs tant bien que mal de faire assez d’offrande à la déesse pour qu’elle ne restaure sa beauté d’antan mais, jusque-là, Lilith n’est jamais revenue. En tant que doyenne de Valgardis, elle est la plus sage de la famille mais cache un passé de guerrière farouche malgré son apparence, nombre de rocréens et de profonds ayant été pourfendus par ses armes.","source_pages":[35,35],"source_designation":"Duché de Volkvangra : Ashilirei Sæbbidottir"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Volkvangra : Ashilirei Sæbbidottir (Valgardis)"],["Nom de la Réalité","_"],["Nom de la Vérité","Ashilirei Sæbbidottir"],["Âge complet","54 ans en apparence ; âge réel inconnu"],["Affiliations","_"],["Nationalité d’origine","Hyperboréenne"],["Nature réelle","Aseryne (hyperboréenne)"],["Statut","Duchesse de Volkvangra"]]},{"type":"p","style":"lore","text":"Ashilirei était régulièrement considérée comme la plus belle femme de tout Hyperborée. L’âge et l’embonpoint lui ont fait perdre ce statut cependant, son influence et sa notoriété sont les plus grandes du continent. La reine-mère et le roi ont cruellement besoin du soutien de la maison Valgardis pour éviter que le conseil des magiciens ne renverse la couronne comme ils le projettent depuis longtemps. Elle a marié sa fille ainée, Aslaug alors qu’elle la désirait voir lui succéder, un sacrifice qui lui a assuré une place de conseillère dans le cercle de la reine-mère. Pourtant, Ashilirei et Hildeveig ne s’aiment pas du tout, et pour cause, la maison Valgardis est issue des immigrés atlantes alors qu’Hildeveig est issue des premiers colons, elles se méprisent réciproquement tout en s’utilisant. Elle vénère Lilith, « Freyja » dans la mythologie nordique, et son palais ducal est aussi un temple de la déesse, Ashilirei essaie d’ailleurs tant bien que mal de faire assez d’offrande à la déesse pour qu’elle ne restaure sa beauté d’antan mais, jusque-là, Lilith n’est jamais revenue. En tant que doyenne de Valgardis, elle est la plus sage de la famille mais cache un passé de guerrière farouche malgré son apparence, nombre de rocréens et de profonds ayant été pourfendus par ses armes."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-blake-unnulf-36","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Blake Unnulf","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Blake Unnulf","real_name_source":"Blake Unnulf","nom_verite":"Bjorgulf Unnulfsson","nom_verite_source":"Bjorgulf Unnulfsson","race":"Aseryne (Hyperboréenne)","age":"26 ans","origine":"Américaine","statut":"Duc","affiliations":"Corporatiste : Ushkoll","source_group":"Hyperborée","source_order":36,"source_page":36,"identity_keys":["Bjorgulf Unnulfsson (Ydmirias)","Ydmirias","Blake Unnulf","Bjorgulf Unnulfsson"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Ydalira : Bjorgulf Unnulfsson (Ydmirias) Nom de la Réalité : Blake Unnulf Nom de la Vérité : Bjorgulf Unnulfsson Age : « 26 ans » ????? Affiliations : Corporatiste : Ushkoll Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Hyperboréenne) Statut : Duc Blake Unnulf est un Américain né en Alaska. Son origine norvégienne remonte à son arrière-grand-père mais il en est assez fier. Bien qu’il envisageât des études pour intégrer la police, il s’est retrouvé à se faire engager en 2027, conscrit par obligation nationale, heureusement, il ne fit pas de bataille sanglante. Après la guerre il fut recruté par Ushkoll sous contrat alaskan. Hélas, récemment, il a été rapatrié au QG californien, découvrant Los Angeles pour la première fois. Duc aseryn, c’est le dirigeant de la maison Ydmirias sur Hyperborée, comme il s’entend assez mal avec la royauté et les autres ducs, il a été mis en exil. En vérité, il cherche un moyen de batte le roi et sa mère et surtout Akryth, qu’il sait être lié à Siadara. C’est un tireur d’exception, préférant les arcs et les arbalètes mais aucune gêné par ls armes à feu.Ce tireur de précision utilise ses dons électro-magnétique d’aseryn pour ajuster sa vision, seule Veronica Silver utiliserait elle aussi ce don par pur instinct, que seule la maison Ydmirias a autant développé sur de nombreuses générations, preuve du génie de la fille de Kalira.","source_pages":[36,36],"source_designation":"Duché d’Ydalira : Bjorgulf Unnulfsson"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Blake Unnulf"],["Âge apparent","26 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Blake Unnulf est un Américain né en Alaska. Son origine norvégienne remonte à son arrière-grand-père mais il en est assez fier. Bien qu’il envisageât des études pour intégrer la police, il s’est retrouvé à se faire engager en 2027, conscrit par obligation nationale, heureusement, il ne fit pas de bataille sanglante. Après la guerre il fut recruté par Ushkoll sous contrat en Alaska. Hélas, récemment, il a été rapatrié au QG californien, découvrant Los Angeles pour la première fois."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Ydalira : Bjorgulf Unnulfsson (Ydmirias)"],["Nom de la Réalité","Blake Unnulf"],["Nom de la Vérité","Bjorgulf Unnulfsson"],["Âge complet","26 ans en apparence ; âge réel inconnu"],["Affiliations","Corporatiste : Ushkoll"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","Duc"]]},{"type":"p","style":"lore","text":"Duc aseryn, c’est le dirigeant de la maison Ydmirias sur Hyperborée, comme il s’entend assez mal avec la royauté et les autres ducs, il a été mis en exil. En vérité, il cherche un moyen de batte le roi et sa mère et surtout Akryth, qu’il sait être lié à Siadara. C’est un tireur d’exception, préférant les arcs et les arbalètes mais aucune gêné par ls armes à feu.Ce tireur de précision utilise ses dons électro-magnétique d’aseryn pour ajuster sa vision, seule Veronica Silver utiliserait elle aussi ce don par pur instinct, que seule la maison Ydmirias a autant développé sur de nombreuses générations, preuve du génie de la fille de Kalira."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-hjor-ornsson-37","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Hjor Ornsson","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Hjor Ornsson","nom_verite_source":"Hjor Ornsson","race":"Aseryne (hyperboréenne)","age":"Âge inconnu","origine":"Hyperboréenne","statut":"duc","affiliations":"Royaume d’hyperborée","source_group":"Hyperborée","source_order":37,"source_page":36,"identity_keys":["Hjor Ornsson (Athoria)","Athoria","Hjor Ornsson"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Valaskjalfir : Hjor Ornsson (Athoria) Nom de la Réalité : _ Nom de la Vérité : Hjor Ornsson Age : « ??? » » Affiliations : Royaume d’hyperborée Nationalité d’origine : Hyperboréenne Ethnie réelle : Aseryne (hyperboréenne) Statut : duc Orns était le duc de la maison Athoria, une grande maison datant de l’Atlantide, issue de guerriers loyaux à la royauté de l’époque dans leur territoire : les Natheas, avant que les Athegos n’unifient l’Atlantide. Orns quitta l’Atlantide la boule au ventre, laissant sa famille qui y fut décimée par les profonds. Il recommença sa vie sur Hyperborée mais jamais n’accepta réellement le roi Siegorn, qu’il savait être un fléau. C’est pour ça que le roi, malgré son apparence juvénile a fait massacrer les Athoria. Il nomma le plus jeune fils, Hjor, âgé de 4 ans, à la tête de la maison. Hjor n’a donc pas connu son père, mais il a hérité de son nom et de sa volonté, de ses mémoires surtout. S’il joue le loyal serviteur de la couronne, il complote pour renverser Siegorn, le fléau d’Hyperborée. Il est prêt à collaborer avec les Mûliens ou les Atlantes, les Lémuriens ou les continentaux, peu lui importe. Il l’ignore mais le roi sait pertinemment ce qu’il projette de faire et la maison Athoria est plus proche que jamais de se faire massacrer à nouveau. Hjor ne va jamais en dehors de l’île-continent, mais il soutient Neera Athren, la renégate, qu’il pense être sa fille cachée même s’il se trompe sur ce sujet.","source_pages":[36,36],"source_designation":"Duché de Valaskjalfir : Hjor Ornsson"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Valaskjalfir : Hjor Ornsson (Athoria)"],["Nom de la Réalité","_"],["Nom de la Vérité","Hjor Ornsson"],["Âge complet","Âge inconnu"],["Affiliations","Royaume d’hyperborée"],["Nationalité d’origine","Hyperboréenne"],["Nature réelle","Aseryne (hyperboréenne)"],["Statut","duc"]]},{"type":"p","style":"lore","text":"Orns était le duc de la maison Athoria, une grande maison datant de l’Atlantide, issue de guerriers loyaux à la royauté de l’époque dans leur territoire : les Natheas, avant que les Athegos n’unifient l’Atlantide. Orns quitta l’Atlantide la boule au ventre, laissant sa famille qui y fut décimée par les profonds. Il recommença sa vie sur Hyperborée mais jamais n’accepta réellement le roi Siegorn, qu’il savait être un fléau. C’est pour ça que le roi, malgré son apparence juvénile a fait massacrer les Athoria. Il nomma le plus jeune fils, Hjor, âgé de 4 ans, à la tête de la maison. Hjor n’a donc pas connu son père, mais il a hérité de son nom et de sa volonté, de ses mémoires surtout. S’il joue le loyal serviteur de la couronne, il complote pour renverser Siegorn, le fléau d’Hyperborée. Il est prêt à collaborer avec les Mûliens ou les Atlantes, les Lémuriens ou les continentaux, peu lui importe. Il l’ignore mais le roi sait pertinemment ce qu’il projette de faire et la maison Athoria est plus proche que jamais de se faire massacrer à nouveau. Hjor ne va jamais en dehors de l’île-continent, mais il soutient Neera Athren, la renégate, qu’il pense être sa fille cachée même s’il se trompe sur ce sujet."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-whitney-ferrell-38","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Whitney Ferrell","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Whitney Ferrell","real_name_source":"Whitney Ferrell","nom_verite":"Thraslaug Kjarandottir","nom_verite_source":"Thraslaug Kjarandottir","race":"Aseryn ((hyperboréenne)","age":"31 ans","origine":"Américaine","statut":"duchesse","affiliations":"Crawlers : mercs","source_group":"Hyperborée","source_order":38,"source_page":37,"identity_keys":["Thraslaug Kjartandottir (Hellunis)","Hellunis","Whitney Ferrell","Thraslaug Kjarandottir"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Eljudniris: Thraslaug Kjartandottir (Hellunis) Nom de la Réalité : Whitney Ferrell Nom de la Vérité : Thraslaug Kjarandottir Age : « 31 ans » Affiliations : Crawlers : mercs Nationalité d’origine : Américaine Ethnie réelle : Aseryn ((hyperboréenne) Statut : duchesse Whitney est surnommée « White chameleon », c’est un crawler efficace et polyvalent, elle n’a pas de spécialité lui étant propre, elle est apte à tout faire, neurodive, mécanique, soins, tir, corps à corps, infiltration, enquête et négociation, elle semble expérimentée dans à peu près tout ce que le boulot offre sans jamais être une experte pour autant. Elle est appréciée des autres crawlers car elle est considérée comme un membre « universel », pouvant remplacer n’importe quel membre à tout moment. Duchesse hyperboréenne de la maison Hellunis, elle a du sang valkyrie en elle, puisque sa mère était Asgeird, la valkyrie d’argent, mère de Herja Gerfrigg, l’actuelle reine valkyrie d’argent au service d’Angrboda, et de Katja. Guerrière exceptionnelle par nature elle adore apprendre et s’ennuyait infiniment sur l’île d’Hyperborée. Elle intégra un temps le Xenoshield de Neera, la formant au combat, avant de faire mercenaire. Elle peut retourner sur l’île en un instant, sa montre possédant un système de téléportation si sa vie est en danger ou si elle l’active, mais elle doit l’alimenter par du sang de voyageur ou de mage. Comme bien des Hyperboréens, elle est terrifiée par le roi Siegorn, craignant une punition.","source_pages":[37,37],"source_designation":"Duché d’Eljudniris : Thraslaug Kjartandottir"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Whitney Ferrell"],["Âge apparent","31 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Whitney est surnommée « White chameleon », c’est un crawler efficace et polyvalent, elle n’a pas de spécialité lui étant propre, elle est apte à tout faire, neurodive, mécanique, soins, tir, corps à corps, infiltration, enquête et négociation, elle semble expérimentée dans à peu près tout ce que le boulot offre sans jamais être une experte pour autant. Elle est appréciée des autres crawlers car elle est considérée comme un membre « universel », pouvant remplacer n’importe quel membre à tout moment."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Eljudniris: Thraslaug Kjartandottir (Hellunis)"],["Nom de la Réalité","Whitney Ferrell"],["Nom de la Vérité","Thraslaug Kjarandottir"],["Âge complet","31 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : mercs"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryn ((hyperboréenne)"],["Statut","duchesse"]]},{"type":"p","style":"lore","text":"Duchesse hyperboréenne de la maison Hellunis, elle a du sang valkyrie en elle, puisque sa mère était Asgeird, la valkyrie d’argent, mère de Herja Gerfrigg, l’actuelle reine valkyrie d’argent au service d’Angrboda, et de Katja. Guerrière exceptionnelle par nature elle adore apprendre et s’ennuyait infiniment sur l’île d’Hyperborée. Elle intégra un temps le Xenoshield de Neera, la formant au combat, avant de faire mercenaire. Elle peut retourner sur l’île en un instant, sa montre possédant un système de téléportation si sa vie est en danger ou si elle l’active, mais elle doit l’alimenter par du sang de voyageur ou de mage. Comme bien des Hyperboréens, elle est terrifiée par le roi Siegorn, craignant une punition."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-thorgerd-glamdottir-39","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Thorgerd Glamdottir","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Hyperborée","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Thorgerd Glamdottir","nom_verite_source":"Thorgerd Glamdottir","race":"Aseryne (Hyperboréenne)","age":"Âge inconnu","origine":"Hyperboréenne","statut":"Duchesse","affiliations":"Royaume d’Hyperborée","source_group":"Hyperborée","source_order":39,"source_page":37,"identity_keys":["Thorgerd Glamdottir (Thorria)","Thorria","Thorgerd Glamdottir"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché de Vingolfa: Thorgerd Glamdottir (Thorria) Nom de la Réalité : _ Nom de la Vérité : Thorgerd Glamdottir Age : « ??? » » Affiliations : Royaume d’Hyperborée Nationalité d’origine : Hyperboréenne Ethnie réelle : Aseryne (Hyperboréenne) Statut : Duchesse La maison Thorria est le dernier vestige des croyances dans le Temple de la Création. A l’origine, quand les dieux prirent l’ascendant par leurs cultes, les prêtresses du culte étaient traquées, alors assez vite, face aux purges, elles se cachèrent dans des familles partisanes, puis ces familles devinrent des familles de « prêtresses ». Après la glaciation d’Hyperborée et le naufrage de l’Atlantide, la famille Thorria retrouva des cultistes de l’Atlantide et pu renouveler ses savoirs et rites. Le Temple reste un culte proscrit en Hyperborée, cependant, la famille Thorria adopte tous les croyants dans son duché. Thorgerd est une prêtresse officieuse du Temple, duchesse et première bretteuse du duché de Vingolfa, elle incarne la perfection aseryne. Elle ne craint pas de confronter le roi ou sa mère face à leurs abus et sa maitrise de la foudre n’a véritablement rien d’exceptionnel surtout pour une prêtresse mais reste suffisant pour détruire l’énergie maléfique du froid d’Akryth et lui éviter d’être gelée si le roi s’énerve. Effrontée et indépendante, elle pratique la lutte Hyperboréenne régulièrement, cachant derrière son apparence de noble, une combattante farouche. Elle est terrifiée par ce que font les humains avec la Réalité, elle méprise l’Humanité autant qu’elle en a peur. Elle ne prend aucun mari, étant prêtresse, n’accepte aucun mariage politique, alors elle compense par l’adoption ayant 31 enfants officiellement.","source_pages":[37,37],"source_designation":"Duché de Vingolfa : Thorgerd Glamdottir"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché de Vingolfa: Thorgerd Glamdottir (Thorria)"],["Nom de la Réalité","_"],["Nom de la Vérité","Thorgerd Glamdottir"],["Âge complet","Âge inconnu"],["Affiliations","Royaume d’Hyperborée"],["Nationalité d’origine","Hyperboréenne"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","Duchesse"]]},{"type":"p","style":"lore","text":"La maison Thorria est le dernier vestige des croyances dans le Temple de la Création. A l’origine, quand les dieux prirent l’ascendant par leurs cultes, les prêtresses du culte étaient traquées, alors assez vite, face aux purges, elles se cachèrent dans des familles partisanes, puis ces familles devinrent des familles de « prêtresses ». Après la glaciation d’Hyperborée et le naufrage de l’Atlantide, la famille Thorria retrouva des cultistes de l’Atlantide et pu renouveler ses savoirs et rites. Le Temple reste un culte proscrit en Hyperborée, cependant, la famille Thorria adopte tous les croyants dans son duché. Thorgerd est une prêtresse officieuse du Temple, duchesse et première bretteuse du duché de Vingolfa, elle incarne la perfection aseryne. Elle ne craint pas de confronter le roi ou sa mère face à leurs abus et sa maîtrise de la foudre n’a véritablement rien d’exceptionnel surtout pour une prêtresse mais reste suffisant pour détruire l’énergie maléfique du froid d’Akryth et lui éviter d’être gelée si le roi s’énerve. Effrontée et indépendante, elle pratique la lutte Hyperboréenne régulièrement, cachant derrière son apparence de noble, une combattante farouche. Elle est terrifiée par ce que font les humains avec la Réalité, elle méprise l’Humanité autant qu’elle en a peur. Elle ne prend aucun mari, étant prêtresse, n’accepte aucun mariage politique, alors elle compense par l’adoption ayant 31 enfants officiellement."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-veronica-silver-40","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Veronica Silver","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Veronica Silver","real_name_source":"Veronica Silver","nom_verite":"Veronica Visilas Athegos","nom_verite_source":"Veronica Visilas Athegos","race":"Aseryne (Serathèenne)","age":"34 ans","origine":"Américaine","statut":"Princesse inconnue de Mû et de l’Atlantide","affiliations":"Crawlers : tous","source_group":"Diaspora & Altéras","source_order":40,"source_page":40,"identity_keys":["Veronica Silver","Veronica Visilas Athegos"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"L’Arbitre : Veronica Silver Nom de la Réalité : Veronica Silver Nom de la Vérité : Veronica Visilas Athegos Age : «34 ans » - Affiliations : Crawlers : tous Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Serathèenne) Statut : Princesse inconnue de Mû et de l’Atlantide Veronica Silver est l’Arbitre des Mafias : elle est intouchable par la Pègre car elle assure le renseignement et la paix entre les factions mafieuses. En retour, elle rend service à toutes ces mafias et tous les gangs si leurs demandes l’intéressen. Elle n’en a pas besoin, mais elle peut aussi débloquer capitaux et matériels par ce réseau. Détective privé officiellement, c’est aussi la meilleure enquêtrice de Californie, la police fait souvent appel à elle.Sa neutralité n’a d’égale que son caractère indépendant et rebelle, personne ne commande la Silver et la Silver ne s’attache à personne. Vétéran de la Guerre, elle est la moins célèbre des Héroines du mémorial de la Guerre, pourtant elle a servi plus longtemps que les autres héros du mémorial, notamment dans l’US. Army. Née des amours de John Silver et de Kalira Athegos, elle a été orpheline dès ses 12 ans quand son père fut tué à la Californian Bank Tower. Après une jeunesse aussi difficile que malsaine, elle s’est émancipée et épanouie dans l’armée et y fit une carrière assez prodigieuse quoi que discrète par le caractère secret des opérations menées. Elle est dotée d’une intelligence supérieure mais ce n’est pas un cadeau pour elle, cherchant le hardcore, la violence et le trash pour se libérer l’esprit. En 2035, elle est incontournable dans la Réalité mais a récemment basculé dans la Vérité, découvrant ses origines et le secret derrière la disparition de sa mère et la mort de son père.","source_pages":[40,40],"source_designation":"L’Arbitre : Veronica Silver"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Veronica Silver"],["Âge apparent","34 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Veronica Silver est l’Arbitre des Mafias : elle est intouchable par la Pègre car elle assure le renseignement et la paix entre les factions mafieuses. En retour, elle rend service à toutes ces mafias et tous les gangs si leurs demandes l’intéressent. Elle n’en a pas besoin, mais elle peut aussi débloquer capitaux et matériels par ce réseau. Détective privée officiellement, c’est aussi la meilleure enquêtrice de Californie, la police fait souvent appel à elle. Sa neutralité n’a d’égale que son caractère indépendant et rebelle, personne ne commande la Silver et la Silver ne s’attache à personne. Vétéran de la Guerre, elle est la moins célèbre des héroïnes du mémorial de la Guerre, pourtant elle a servi plus longtemps que les autres héros du mémorial, notamment dans l’US Army."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","L’Arbitre : Veronica Silver"],["Nom de la Réalité","Veronica Silver"],["Nom de la Vérité","Veronica Visilas Athegos"],["Âge complet","34 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : tous"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Serathèenne)"],["Statut","Princesse inconnue de Mû et de l’Atlantide"]]},{"type":"p","style":"lore","text":"Née des amours de John Silver et de Kalira Athegos, elle a été orpheline dès ses 12 ans quand son père fut tué à la Californian Bank Tower. Après une jeunesse aussi difficile que malsaine, elle s’est émancipée et épanouie dans l’armée et y fit une carrière assez prodigieuse quoi que discrète par le caractère secret des opérations menées. Elle est dotée d’une intelligence supérieure mais ce n’est pas un cadeau pour elle, cherchant le hardcore, la violence et le trash pour se libérer l’esprit. En 2035, elle est incontournable dans la Réalité mais a récemment basculé dans la Vérité, découvrant ses origines et le secret derrière la disparition de sa mère et la mort de son père."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-jack-grey-41","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Jack Grey","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Jack Grey","real_name_source":"Jack Grey","nom_verite":"John Silver","nom_verite_source":"_","race":"Aseryne (Serathèenne)","age":"56 ans","origine":"américaine","statut":"plus puissant spectre californien","affiliations":"créatures : spectres","source_group":"Diaspora & Altéras","source_order":41,"source_page":40,"identity_keys":["Jack Grey","John Silver"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Le Vetala orage : Jack Grey Nom de la Réalité : Jack Grey Nom de la Vérité : _ Age : « 56ans » - Affiliations : créatures : spectres Nationalité d’origine : américaine Ethnie réelle : Aseryne (Serathèenne) Statut : plus puissant spectre californien Jack Grey est un Vetalas, la classe la plus puissante des fantômes. Contrairement aux autres fantômes de son genre, il semble très sain d’esprit et moins sanguinaire. Il sert Dina Page dont les dons nécromantiques sont si puissants qu’elle est la seule à l’avoir arrêté. Il est grandement amnésique depuis sa mort, il sait qu’il était policier et qu’il avait une gamine : Valeria, qu’il doit retrouver, mais il ne se souvient pas de son visage. De tous les Vetalas, il est le seul connu capable de générer un orage électrique, par sa nature Aseryne, seule la reine des vetalas le surpasse en puissance spectrale tant sa haine et son envie de vengeance sont grands. Sans Dina, il aurait rasé Los Angeles. Il a une haine profonde pour les cartels et la mafia italienne. Malgré son calme apparent, c’est un être de colère et de vengeance qui a été créé par le décès d’un aseryn et les pouvoirs du conseil de la Foudre, par erreur. Sa mémoire spectrale lui faisant défaut, il ignore qu’il était John Silver et que sa fille est Veronica, il ignore être mort il y a 22 ans et encore plus qu’il était le fils de Saerith , la fille ainée de Kyriak et d’Ouranos, un dive primordial. Seule Dina contient sa colère et le garde « humain », il l’adore et la protège en retour.","source_pages":[40,40],"source_designation":"Le Vetala orage : Jack Grey"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Jack Grey"],["Âge apparent","56 ans"],["Nationalité déclarée","américaine"]]},{"type":"p","text":"Jack Grey est un ancien policier américain de 56 ans. D’un calme apparent, il nourrit une haine profonde envers les cartels et la mafia italienne."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Le Vetala orage : Jack Grey"],["Nom de la Réalité","Jack Grey"],["Nom de la Vérité","John Silver"],["Âge complet","56 ans en apparence ; âge réel inconnu"],["Affiliations","créatures : spectres"],["Nationalité d’origine","américaine"],["Nature réelle","Aseryne (Serathèenne)"],["Statut","plus puissant spectre californien"]]},{"type":"p","style":"lore","text":"Jack Grey est un Vetala, la classe la plus puissante des fantômes. Contrairement aux autres fantômes de son genre, il semble très sain d’esprit et moins sanguinaire. Il sert Dina Page dont les dons nécromantiques sont si puissants qu’elle est la seule à l’avoir arrêté. Il est grandement amnésique depuis sa mort, il sait qu’il était policier et qu’il avait une gamine : Valeria, qu’il doit retrouver, mais il ne se souvient pas de son visage. De tous les Vetalas, il est le seul connu capable de générer un orage électrique, par sa nature Aseryne, seule la reine des vetalas le surpasse en puissance spectrale tant sa haine et son envie de vengeance sont grands. Sans Dina, il aurait rasé Los Angeles. Il a une haine profonde pour les cartels et la mafia italienne. Malgré son calme apparent, c’est un être de colère et de vengeance qui a été créé par le décès d’un aseryn et les pouvoirs du conseil de la Foudre, par erreur. Sa mémoire spectrale lui faisant défaut, il ignore qu’il était John Silver et que sa fille est Veronica, il ignore être mort il y a 22 ans et encore plus qu’il était le fils de Saerith , la fille ainée de Kyriak et d’Ouranos, un dive primordial. Seule Dina contient sa colère et le garde « humain », il l’adore et la protège en retour."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-neera-athren-42","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Neera Athren","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Neera Athren","real_name_source":"« Nea » - Neera Athren","nom_verite":"Neera Athren","nom_verite_source":"Neera Athren","race":"Aseryne (Hyperboréenne)","age":"34 ans","origine":"Américaine","statut":"renégate","affiliations":"crawlers : gundrivers/ Chasseurs : Xenoshield","source_group":"Diaspora & Altéras","source_order":42,"source_page":41,"identity_keys":["Neera Athren","« Nea » - Neera Athren","Nea"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Fondatrice du Xenoshield: Neera Athren Nom de la Réalité : « Nea » - Neera Athren Nom de la Vérité : Neera Athren Age : «34 ans » - ??? Affiliations : crawlers : gundrivers/ Chasseurs : Xenoshield Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Hyperboréenne) Statut : renégate Nea est une motarde qui fait gundriver, une sorte de transporteur armé, elle n’a pas néanmoins qu’une réputation très mineure dans le métier, pas très fiable. La raison est qu’elle passe son temps dans son armure cybernétique, elle est « Neera l’exterminateur », le chef mystérieux à la tête du Xenoshield dont personne ne connait le visage dans cette organisation de tueurs d’aliens où on la considère comme un homme. Née sur le continent d’Hyperborée, sa mère était une pauvre fille fantasmant la noblesse Hyperboréenne et qui trompa son partenaire régulièrement. Après une relation avec le duc de la maison Athoria, elle eut Neera, et joua pour que Hjor ne pense qu’il s’agissait bien sa fille. Hélas, ça n’a pas empêcher la mère et ses autres filles d’être capturées et abusée par des rocréens abyssaux sous les yeux de la jeune Neera qui vola de nombreuses choses et préféra fuir. Avec le Stroethil, elle fit forger une armure technologique unique. Elle tortura des prêtresses mûliennes et atlantes pour apprendre les bases du don de la foudre afin d’optimiser son armure. Depuis, elle lutte contre les envahisseurs extraterrestres, emplie de vengeance et tue les hyperboréens venus la traquer.","source_pages":[41,41],"source_designation":"Fondatrice du Xenoshield : Neera Athren","protect_truth_metadata":true},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Neera Athren"],["Âge apparent","34 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Nea est une motarde qui fait gundriver, une sorte de transporteur armé, elle n’a néanmoins qu’une réputation très mineure dans le métier, pas très fiable."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Fondatrice du Xenoshield : Neera Athren"],["Nom de la Réalité","Neera Athren"],["Nom de la Vérité","Neera Athren"],["Âge complet","34 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers : gundrivers/ Chasseurs : Xenoshield"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Hyperboréenne)"],["Statut","renégate"]]},{"type":"p","style":"lore","text":"La raison est qu’elle passe son temps dans son armure cybernétique, elle est « Neera l’exterminateur », le chef mystérieux à la tête du Xenoshield dont personne ne connait le visage dans cette organisation de tueurs d’aliens où on la considère comme un homme. Née sur le continent d’Hyperborée, sa mère était une pauvre fille fantasmant la noblesse Hyperboréenne et qui trompa son partenaire régulièrement. Après une relation avec le duc de la maison Athoria, elle eut Neera, et joua pour que Hjor ne pense qu’il s’agissait bien sa fille. Hélas, cela n’a pas empêché la mère et ses autres filles d’être capturées et abuséesss par des rocréens abyssaux sous les yeux de la jeune Neera qui vola de nombreuses choses et préféra fuir. Avec le Stroethil, elle fit forger une armure technologique unique. Elle tortura des prêtresses mûliennes et atlantes pour apprendre les bases du don de la foudre afin d’optimiser son armure. Depuis, elle lutte contre les envahisseurs extraterrestres, emplie de vengeance et tue les hyperboréens venus la traquer."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-gina-sunheart-43","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Gina Sunheart","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Gina Sunheart","real_name_source":"Gina Sunheart","nom_verite":"","nom_verite_source":"_","race":"Aseryne (serathèenne)","age":"34 ans","origine":"américaine (Cherokee)","statut":"Conseillère","affiliations":"crawlers : Enders","source_group":"Diaspora & Altéras","source_order":43,"source_page":41,"identity_keys":["Gina Sunheart"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Conseillère : Gina Sunheart Nom de la Réalité : Gina Sunheart Nom de la Vérité : _ Age : «34 ans » - ??? Affiliations : crawlers : Enders Nationalité d’origine : américaine (Cherokee) Ethnie réelle : Aseryne (serathèenne) Statut : Conseillère Gina est une amérindienne, anciennement serveuse de nightclub entre deux petits rôles de native lambda, elle a totalement changé de vie avec la guerre, son mari fut conscrit puis y décéda. Elle s’est réfugiée dans l’alcool avant de retrouver une raison de vivre dans la Grande Réserve à renouer avec ses ancêtres. Serathèenne, cette humaine au sang d’Aseryn est membre du conseil depuis plus d’un siècle. Elle est la plus rattachée à la Réalité mais la moins attachée aux rites aseryns. Elle déteste corps et âme servir de vaisseau à des esprits d’anciens conseillers, mais elle a un pacte chamanique avec une vingtaine d’entre eux. En 2014, c’est elle qui trouva l’âme de John Silver et, croyant que c’était un des siens, la chamane essaya de le lier à la Grotte de la foudre, mais quand la rage du spectre éclata, elle lui effaça ses souvenirs, faute de le vaincre, ne faisant qu’augmenter sa puissance. Elle n’a rien avoir avec le conseil de la grande réserve, regroupant mages et garous, mais elle est amie avec Naalnish, qu’elle aide, ce dernier s’étant présenté comme un descendant de l’oiseau-tonnerre. Assez prétentieuse, elle reste une chamane plutôt rude et indépendante.","source_pages":[41,41],"source_designation":"Conseillère : Gina Sunheart","protect_truth_metadata":true},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Gina Sunheart"],["Âge apparent","34 ans"],["Nationalité déclarée","américaine (Cherokee)"]]},{"type":"p","text":"Gina est une amérindienne, anciennement serveuse de nightclub entre deux petits rôles de native lambda, elle a totalement changé de vie avec la guerre, son mari fut conscrit puis y décéda. Elle s’est réfugiée dans l’alcool avant de retrouver une raison de vivre dans la Grande Réserve, en renouant avec ses ancêtres."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Conseillère : Gina Sunheart"],["Nom de la Réalité","Gina Sunheart"],["Nom de la Vérité","Non renseigné"],["Âge complet","34 ans en apparence ; âge réel inconnu"],["Affiliations","crawlers : Enders"],["Nationalité d’origine","américaine (Cherokee)"],["Nature réelle","Aseryne (serathèenne)"],["Statut","Conseillère"]]},{"type":"p","style":"lore","text":"Serathèenne, cette humaine au sang d’Aseryn est membre du conseil depuis plus d’un siècle. Elle est la plus rattachée à la Réalité mais la moins attachée aux rites aseryns. Elle déteste corps et âme servir de vaisseau à des esprits d’anciens conseillers, mais elle a un pacte chamanique avec une vingtaine d’entre eux. En 2014, c’est elle qui trouva l’âme de John Silver et, croyant que c’était un des siens, la chamane essaya de le lier à la Grotte de la foudre, mais quand la rage du spectre éclata, elle lui effaça ses souvenirs, faute de le vaincre, ne faisant qu’augmenter sa puissance. Elle n’a rien avoir avec le conseil de la grande réserve, regroupant mages et garous, mais elle est amie avec Naalnish, qu’elle aide, ce dernier s’étant présenté comme un descendant de l’oiseau-tonnerre. Assez prétentieuse, elle reste une chamane plutôt rude et indépendante."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-sanuwa-44","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Sanuwa","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Sanuwa","real_name_source":"Sanuwa","nom_verite":"Sanuwa","nom_verite_source":"Sanuwa","race":"Aseryne (Serathèenne)","age":"44 ans","origine":"Américaine","statut":"Conseiller","affiliations":"_","source_group":"Diaspora & Altéras","source_order":44,"source_page":42,"identity_keys":["Oiseau-Tonnerre","Sanuwa"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Conseiller : Oiseau-Tonnerre Nom de la Réalité : Sanuwa Nom de la Vérité : Sanuwa Age : « 44 ans » - ??? Affiliations : _ Nationalité d’origine : Américaine Ethnie réelle : Aseryne (Serathèenne) Statut : Conseiller Sanuwa est un Serathèen d’Amériques. Il est assez ancien, il est un arrière-petit-fils de Serathè et d’un esprit rapace, c’est lui qui inspira les nombreuses légendes d’oiseau-tonnerre en Amériques. Mi￾esprit mi aseryn, il incarne l’orage à l’état brut. Comme c’est un esprit il est immortel et veille sur le conseil depuis sa création. Il est un des plus grands ennemis de Quetzalcoatl mais aussi de Naalnish, le corbeau trompeur. Il n’apprécie pas les aseryns purs car ils l’ont autrefois rejeté, au contraire, il a une tendresse rare pour les humains natifs et leurs cultures. Il a fait la paix avec les garous des pelages sombres et roux après des millénaire de haine contre eux. Particulièrement prétentieux et prompt à l’agressivité, c’est un être qui se pense supérieur, qui côtoie le divin de fait, effectivement, nombreux sont les Daemons qui ne peuvent rien contre lui d’autant plus depuis lé déchéance d’Abigor. Il a pour quête personnelle de retrouver un spectre du conseil qui s’est échappé, une ancienne chamane Serathèenne étant allé se soumettre de son vivant à la loge amérindienne de l’est.","source_pages":[42,42],"source_designation":"Conseiller : Oiseau-Tonnerre","protect_truth_metadata":true},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Sanuwa"],["Âge apparent","44 ans"],["Nationalité déclarée","Américaine"]]},{"type":"p","text":"Sanuwa est un Américain de 44 ans, prétentieux et prompt à l’agressivité, qui manifeste une tendresse rare pour les cultures amérindiennes."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Conseiller : Oiseau-Tonnerre"],["Nom de la Réalité","Sanuwa"],["Nom de la Vérité","Sanuwa"],["Âge complet","44 ans en apparence ; âge réel inconnu"],["Affiliations","Non renseignées"],["Nationalité d’origine","Américaine"],["Nature réelle","Aseryne (Serathèenne)"],["Statut","Conseiller"]]},{"type":"p","style":"lore","text":"Sanuwa est un Serathèen d’Amériques. Il est assez ancien, il est un arrière-petit-fils de Serathè et d’un esprit rapace, c’est lui qui inspira les nombreuses légendes d’oiseau-tonnerre en Amériques. Mi-esprit mi aseryn, il incarne l’orage à l’état brut. Comme c’est un esprit il est immortel et veille sur le conseil depuis sa création. Il est un des plus grands ennemis de Quetzalcoatl mais aussi de Naalnish, le corbeau trompeur. Il n’apprécie pas les aseryns purs car ils l’ont autrefois rejeté, au contraire, il a une tendresse rare pour les humains natifs et leurs cultures. Il a fait la paix avec les garous des pelages sombres et roux après des millénaire de haine contre eux. Particulièrement prétentieux et prompt à l’agressivité, c’est un être qui se pense supérieur, qui côtoie le divin de fait, effectivement, nombreux sont les Daemons qui ne peuvent rien contre lui d’autant plus depuis lé déchéance d’Abigor. Il a pour quête personnelle de retrouver un spectre du conseil qui s’est échappé, une ancienne chamane Serathèenne étant allé se soumettre de son vivant à la loge amérindienne de l’est."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-iwashita-koji-45","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Iwashita Koji","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Iwashita Koji","real_name_source":"Iwashita Koji","nom_verite":"Iwashita Koji","nom_verite_source":"Iwashita Koji","race":"Aseryne (Serathèenne)","age":"42 ans","origine":"japonaise","statut":"_","affiliations":"Crawlers : voidrunner/ chasseurs","source_group":"Diaspora & Altéras","source_order":45,"source_page":42,"identity_keys":["Iwashita Koji"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Indépendant : Iwashita Koji Nom de la Réalité : Iwashita Koji Nom de la Vérité : Iwashita Koji Age : «42 ans » - ??? Affiliations : Crawlers : voidrunner/ chasseurs Nationalité d’origine : japonaise Ethnie réelle : Aseryne (Serathèenne) Statut : _ Koji est un assassin issu de la famille Iwashita, laquelle gardait le katana maudit Musaboken. Après une attaque de yokai, le sabre fut dérobé et emmené aux Etats-Unis. Koji ayant perdu sa famille durant le vol, se rua à la poursuite des criminels. Il ne retrouva pas son katana familial mais ses enquêtes lui coutant de l’argent, il fut rapidement forcé de faire des petits boulots, doué comme personne pour la chasse à l’homme mais surtout celle aux monstres, il monta au sein de l’Association des chasseurs et entra dans le légendaire Hunt15, soit les 15 meilleurs chasseurs. Son sang aseryn semble lui donner des dons extraordinaires avec la foudre, mais c’est surtout qu’en tant qu’exorciste shinto que cette affinité fonctionne, par de pactes avec des esprits de l’orage (des nymphes). S’il est doué au combat, il a besoin d’une armure technologique pour faire face aux plus terribles ennemis, le modèle a été développé par Sehdia craft et s’avère le seul modèle d’armure assistée capable de suivre ses mouvements surhumains. Il est convaincu que Fuyumi Shinoda possède son katana, en vérité, elle en possède bien un maudit, par un fléau comme le sien mais il reste différent. Koji est un homme assez discret mais redoutable.","source_pages":[42,42],"source_designation":"Indépendant : Iwashita Koji","protect_truth_metadata":true},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Iwashita Koji"],["Âge apparent","42 ans"],["Nationalité déclarée","japonaise"]]},{"type":"p","text":"Koji est un assassin issu de la famille Iwashita, laquelle gardait le katana maudit Musaboken. Après une attaque de yokai, le sabre fut dérobé et emmené aux États-Unis. Koji ayant perdu sa famille durant le vol, se rua à la poursuite des criminels. Il ne retrouva pas son katana familial mais ses enquêtes lui coûtant de l’argent, il fut rapidement forcé de faire des petits boulots."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Indépendant : Iwashita Koji"],["Nom de la Réalité","Iwashita Koji"],["Nom de la Vérité","Iwashita Koji"],["Âge complet","42 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : voidrunner/ chasseurs"],["Nationalité d’origine","japonaise"],["Nature réelle","Aseryne (Serathèenne)"],["Statut","Non renseigné"]]},{"type":"p","style":"lore","text":"Doué comme personne pour la chasse à l’homme mais surtout celle aux monstres, il monta au sein de l’Association des chasseurs et entra dans le légendaire Hunt15, soit les 15 meilleurs chasseurs. Son sang aseryn semble lui donner des dons extraordinaires avec la foudre, mais c’est surtout qu’en tant qu’exorciste shinto que cette affinité fonctionne, par des pactes avec des esprits de l’orage (des nymphes). S’il est doué au combat, il a besoin d’une armure technologique pour faire face aux plus terribles ennemis, le modèle a été développé par Sehdia craft et s’avère le seul modèle d’armure assistée capable de suivre ses mouvements surhumains. Il est convaincu que Fuyumi Shinoda possède son katana, en vérité, elle en possède bien un maudit, par un fléau comme le sien mais il reste différent. Koji est un homme assez discret mais redoutable."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-naedessia-valendis-46","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Naedessia Valendis","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Naedessia Valendis","nom_verite_source":"Naedessia Valendis","race":"Aseryne (atlantes de Gaerras)","age":"24 ans en apparence ; âge réel inconnu","origine":"Atlante (Duché d’Altéras)","statut":"Duchesse","affiliations":"_","source_group":"Diaspora & Altéras","source_order":46,"source_page":43,"identity_keys":["Naedessia Valendis"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Duché d’Altéras : Naedessia Valendis Nom de la Réalité : _ Nom de la Vérité : Naedessia Valendis Age : « 24 ans » - ??? Affiliations : _ Nationalité d’origine : Atlante (Duché d’Altéras) Ethnie réelle : Aseryne (atlantes de Gaerras) Statut : Duchesse Naedessia était une jeune descendante de la maison Valendis, née sur Aèr, elle se retrouva à devoir gérer un domaine du Duché d’Aerilin plus enfoncé dans les duchés de l’Est. S’en sortant avec un génie rare, elle monta dans l’échelle sociale atlantes sur Aèr jusqu’à ce que la reine Kalira ne revienne de son voyage sur Gaerras seconde. Après un entretien avec la reine Lorinae, il ft établi que le monde de Gaerras semblait propice à l’installation d’un duché Atlante afin de commercer et de disposer d’un autre monde en cas de catastrophe. Naedessia s’était illustrée par une certaine audace alors elle fut nommée à la charge de cette colonie. Face à la réussite de l’installation, même si Kalira avait déjà fait le gros du travail diplomatique, Naedessia fut élevée au rang de Duchesse Atlante. Altéras eut énormément de difficultés avec les grandes crises sur Gaerras mais l’alliance entre Khan, Lekyu, Doboriah et Altéras assura aux atlantes, les « Altérassiens », une grande stabilité malgré les obstacles. Le duché d’Altéras accoucha d’un second duché, le duché d’Hydrelias, mais le duc de ce duché était un usurpateur ayant assassiné celui choisi par la reine, Naedessia ne se laissa pas duper et une gurerre sanglante entraina la chute du jeune duché, que Naedessia intégra au sien non sans être critiquée par les autres ducs.","source_pages":[43,43],"source_designation":"Duché d’Altéras : Naedessia Valendis"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Duché d’Altéras : Naedessia Valendis"],["Nom de la Réalité","Aucune couverture humaine renseignée"],["Nom de la Vérité","Naedessia Valendis"],["Âge complet","24 ans en apparence ; âge réel inconnu"],["Affiliations","Non renseignées"],["Nationalité d’origine","Atlante (Duché d’Altéras)"],["Nature réelle","Aseryne (atlantes de Gaerras)"],["Statut","Duchesse"]]},{"type":"p","style":"lore","text":"Naedessia était une jeune descendante de la maison Valendis, née sur Aèr, elle se retrouva à devoir gérer un domaine du Duché d’Aerilin plus enfoncé dans les duchés de l’Est. S’en sortant avec un génie rare, elle monta dans l’échelle sociale atlantes sur Aèr jusqu’à ce que la reine Kalira ne revienne de son voyage sur Gaerras seconde. Après un entretien avec la reine Lorinae, il ft établi que le monde de Gaerras semblait propice à l’installation d’un duché Atlante afin de commercer et de disposer d’un autre monde en cas de catastrophe. Naedessia s’était illustrée par une certaine audace alors elle fut nommée à la charge de cette colonie. Face à la réussite de l’installation, même si Kalira avait déjà fait le gros du travail diplomatique, Naedessia fut élevée au rang de Duchesse Atlante. Altéras eut énormément de difficultés avec les grandes crises sur Gaerras mais l’alliance entre Khan, Lekyu, Doboriah et Altéras assura aux atlantes, les « Altérassiens », une grande stabilité malgré les obstacles. Le duché d’Altéras accoucha d’un second duché, le duché d’Hydrelias, mais le duc de ce duché était un usurpateur ayant assassiné celui choisi par la reine, Naedessia ne se laissa pas duper et une gurerre sanglante entraina la chute du jeune duché, que Naedessia intégra au sien non sans être critiquée par les autres ducs."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"},{"id":"pnj-aseryns-terres-temples-arthur-delight-47","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Arthur Delight","source":"faction_les continents Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Diaspora & Altéras","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"Arthur Delight","real_name_source":"Arthur Delight","nom_verite":"Astharyn Dellioth","nom_verite_source":"Astharyn Dellioth","race":"Aseryne (atlantes de Gaerras)","age":"32 ans","origine":"américain","statut":"usurpateur (Hydrelias)","affiliations":"Crawlers : fixer","source_group":"Diaspora & Altéras","source_order":47,"source_page":43,"identity_keys":["Astharyn Delliot","Arthur Delight","Astharyn Dellioth"],"source_documents":["faction_les continents Aseryns(1)(1).pdf"],"source_extract":"Indépendant : Astharyn Delliot Nom de la Réalité : Arthur Delight Nom de la Vérité : Astharyn Dellioth Age : «32 ans » - ??? Affiliations : Crawlers : fixer Nationalité d’origine : américain Ethnie réelle : Aseryne (atlantes de Gaerras) Statut : usurpateur (Hydrelias) Arthur Delight est un fixer pitoyable, il a a réputation de proposer essentiellement des coups foireux ou des missions suicide, c’est un fixer qui prend n’importe quel crawler, alors il est parfois le dernier espoir pour ceux les plus méprisés ou les débutants. C’est une ordure finie mais qui aime les ordures lui-même, épargnant souvent les pires raclures pour ses missions merdiques. Usurpateur, il se présenta comme le duc d’Hydrelias envoyé par Lorinae sur Gaerras. Il avait des lettres ornées du sceau d’Aerlith, la sœur de la reine alors pendant un temps, seule Naedessia eut un doute. Astharyn se présenta comme le fils d’Aerlith quand on le mit au pied du mur, qu’elle aurait eu avc l’archidémon Zehol. S’il possède effectivement une forte magie démoniaque, Astharyn ne semble pas être un démon de Gaerras et il a très peu en commun avec Aerlith qu’il pense sincèrement être sa mère, en vérité, il n’est le fils que d’une de ses servantes et il semble plus probable que son père soit un diablotin sans nom. Sur Terre pour se réfugier, il se délect des conflits entre Aseryn qu’il essaye d’envenimer au possible par de basses manipulations.","source_pages":[43,43],"source_designation":"Indépendant : Astharyn Delliot"},"sections":[{"id":"aseryn-identite-realite","title":"Identité · Réalité","level":2,"blocks":[{"type":"table","rows":[["Champ","Valeur"],["Nom / identité de Réalité","Arthur Delight"],["Âge apparent","32 ans"],["Nationalité déclarée","américain"]]},{"type":"p","text":"Arthur Delight est un fixer pitoyable, il a la réputation de proposer essentiellement des coups foireux ou des missions suicide, c’est un fixer qui prend n’importe quel crawler, alors il est parfois le dernier espoir pour ceux les plus méprisés ou les débutants. C’est une ordure finie mais qui aime lui-même les ordures, épargnant souvent les pires raclures pour ses missions merdiques."}]},{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Indépendant : Astharyn Delliot"],["Nom de la Réalité","Arthur Delight"],["Nom de la Vérité","Astharyn Dellioth"],["Âge complet","32 ans en apparence ; âge réel inconnu"],["Affiliations","Crawlers : fixer"],["Nationalité d’origine","américain"],["Nature réelle","Aseryne (atlantes de Gaerras)"],["Statut","usurpateur (Hydrelias)"]]},{"type":"p","style":"lore","text":"Usurpateur, il se présenta comme le duc d’Hydrelias envoyé par Lorinae sur Gaerras. Il avait des lettres ornées du sceau d’Aerlith, la sœur de la reine alors pendant un temps, seule Naedessia eut un doute. Astharyn se présenta comme le fils d’Aerlith quand on le mit au pied du mur, qu’elle aurait eu avec l’archidémon Zehol. S’il possède effectivement une forte magie démoniaque, Astharyn ne semble pas être un démon de Gaerras et il a très peu en commun avec Aerlith qu’il pense sincèrement être sa mère, en vérité, il n’est le fils que d’une de ses servantes et il semble plus probable que son père soit un diablotin sans nom. Sur Terre pour se réfugier, il se délect des conflits entre Aseryn qu’il essaye d’envenimer au possible par de basses manipulations."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"pnj-aseryns-terres-temples-kyrtareth-48","dataset":"verite-aseryns-terres-temples-pnj","category":"Personnages","sourceCategory":"Vérité","title":"Kyrtareth","source":"Les temples Aseryns(1)(1).pdf","status":"canon_source","rebuildV2":true,"tags":["Vérité","PNJ","Aseryns","Ordre Sépulcral","Aseryns terres & temples 2026-09"],"pnj":{"completeness":"detailed","real_name":"","real_name_source":"_","nom_verite":"Kyrtareth","nom_verite_source":"Kyrtareth","race":"Aseryne (paleo-atlante)","age":"40 ans en apparence ; âge réel inconnu","origine":"Atlante","statut":"grande maîtresse","affiliations":"_","source_group":"Ordre Sépulcral","source_order":48,"source_page":7,"identity_keys":["Kyrtareth Serath","Kyrtareth"],"source_documents":["Les temples Aseryns(1)(1).pdf"],"source_extract":"Grande maitresse: Kyrtareth Serath Nom de la Réalité : _ Nom de la Vérité : Kyrtareth Age : «40 ans » - ??? ns Affiliations : _ Nationalité d’origine : Atlante Ethnie réelle : Aseryne (paleo-atlante) Statut : grande maîtresse Tous les membre de l’ordre sont de la même famille : les Serath. Ils perdent tous leur nom de famille en accédant à l’armure sacrée du Stroethil, ceux qui n’en avaient pas en gagnent un. Kyrtareth est l’actuelle grande maitresse et bien qu’elle n’en impose pas forcément par sa carrure ou son armure, très simple, Kyrtareth est une femme qui sait se faire obéir, en effet, sa voix, rôdée à l’ancien aseryn, cette langue créée par Serathè en personne, fait qu’elle est particulièrement autoritaire, elle claque chaque mot comme un coup de tonnerre au point que chaque aseryn l’entendant sent sa colonne vertébrale se courber d’instinct et tous ses nerfs être parcouru de l’ordre donné. Peut-être descend-elle d’une très haute lignée, elle ne l’avouera jamais car sa seule famille est celle de l’Ordre sépulcral. Elle est à la fois la plus fine lame, la plus fine maitresse de la foudre et la plus puissante incantatrice dans la « langue-tonnerre » au sein de l’ordre. Elle ne respecte absolument pas les prêtresses du temple d’ailleurs, elle a une haine profonde pour Kalireth et ses yeux d’or, qu’elle sait venir des fléaux. Elle a une profonde sympathie pour Lorinae Darksun en revanche.","source_pages":[7,7],"source_designation":"Grande maîtresse : Kyrtareth Serath"},"sections":[{"id":"aseryn-dossier-mj","title":"Dossier MJ · Vérité & informations cachées","level":2,"audience":"mj","blocks":[{"type":"table","rows":[["Champ","Valeur"],["Repère source","Grande maîtresse : Kyrtareth Serath"],["Nom de la Réalité","Aucune couverture humaine renseignée"],["Nom de la Vérité","Kyrtareth"],["Âge complet","40 ans en apparence ; âge réel inconnu"],["Affiliations","Non renseignées"],["Nationalité d’origine","Atlante"],["Nature réelle","Aseryne (paleo-atlante)"],["Statut","grande maîtresse"]]},{"type":"p","style":"lore","text":"Tous les membres de l’ordre sont de la même famille : les Serath. Ils perdent tous leur nom de famille en accédant à l’armure sacrée du Stroethil, ceux qui n’en avaient pas en gagnent un. Kyrtareth est l’actuelle grande maitresse et bien qu’elle n’en impose pas forcément par sa carrure ou son armure, très simple, Kyrtareth est une femme qui sait se faire obéir, en effet, sa voix, rôdée à l’ancien aseryn, cette langue créée par Serathè en personne, fait qu’elle est particulièrement autoritaire, elle claque chaque mot comme un coup de tonnerre au point que chaque aseryn l’entendant sent sa colonne vertébrale se courber d’instinct et tous ses nerfs être parcouru de l’ordre donné. Peut-être descend-elle d’une très haute lignée, elle ne l’avouera jamais car sa seule famille est celle de l’Ordre sépulcral. Elle est à la fois la plus fine lame, la plus fine maitresse de la foudre et la plus puissante incantatrice dans la « langue-tonnerre » au sein de l’ordre. Elle ne respecte absolument pas les prêtresses du temple d’ailleurs, elle a une haine profonde pour Kalireth et ses yeux d’or, qu’elle sait venir des fléaux. Elle a une profonde sympathie pour Lorinae Darksun en revanche."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}],"audience":"mj"}] as Array<Record<string, any>>;
